import * as React from "react"
import { useContext } from "react"
import { ConfigContext } from "../config/config-provider"
import ImageSpread from './image-spread'
import type { ImageOption } from './image-with-options'
import { resolveImageAnchorInsets } from './image-anchor-geometry'
import {
  renderOverlay,
  renderOptionsButton,
  useShouldShowOptions,
} from './image-overlay-utils'

interface ImageSpreadWithOverlayProps {
  className?: string
  style?: React.CSSProperties
  overlaySvg?: string
  overlayClassName?: string
  options?: ImageOption[]
  dialog?: Record<string, any> | null
  dialogProps?: Record<string, any>
  spreadProps: any
  children?: React.ReactNode
}

const ImageSpreadWithOverlay = ({
  overlaySvg,
  overlayClassName,
  options = [],
  dialog,
  spreadProps,
  children,
}: ImageSpreadWithOverlayProps) => {
  const config = useContext(ConfigContext)
  const showOptions = useShouldShowOptions(options)
  const anchorInsets = resolveImageAnchorInsets(
    {
      ...spreadProps,
      pageWidth: spreadProps?.pageWidth ?? config?.page?.width ?? 210,
      bleed: spreadProps?.bleed ?? config?.page?.bleed ?? 0,
    },
    'spread'
  )

  // Render spread with overlay inside the image container
  // Pass dialog prop to ImageSpread so click-to-edit targets the image area
  // No relative wrapper - it breaks absolute positioning! The options button is anchored
  // to the visible half of the spread instead (see image-anchor-geometry).
  return (
    <>
      <ImageSpread {...spreadProps} dialog={dialog}>
        {renderOverlay(overlaySvg, overlayClassName)}
        {children}
      </ImageSpread>
      {renderOptionsButton(options, showOptions, anchorInsets)}
    </>
  )
}

export default ImageSpreadWithOverlay
