import * as React from "react"
import { GripVertical, ArrowUpDown, Lock, Plus } from "lucide-react"
import DragDropGrid from "../../utility/drag-drop-grid"
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter } from "../../ui/sheet"
import { Badge } from "../../ui/badge"
import { Button } from "../../ui/button"
import { createDefaultRenderThumbnail } from "./default-render-thumbnail"
import type { PageComponent } from "./page-group-utils"
import { useShellTranslation } from "../../i18n/locale-context"
import type { LocalizedText } from "../../i18n/i18n-core.js"

export interface PageItem {
  id: string
  [key: string]: any
}

export interface PageOrderDialogProps<T extends PageItem> {
  open: boolean
  onOpenChange: (open: boolean) => void
  pages: T[]
  onReorder: (newOrder: T[]) => void
  onRemove?: (item: T) => void
  renderThumbnail?: (page: T, index: number, isDragging?: boolean) => React.ReactNode
  
  // NEW: For automatic thumbnail rendering
  pageComponents?: { [pageId: string]: PageComponent }
  payload?: any
  
  // Page setup (same as Pagination setup prop) - supports format/orientation or explicit width/height in mm
  setup?: { width?: number; height?: number; [key: string]: any }
  
  title?: LocalizedText
  description?: LocalizedText
  gridColsClass?: string
}

// Default page thumbnail component with simple preview
function DefaultPageThumbnail<T extends PageItem>({
  page,
  index,
  isDragging,
}: {
  page: T
  index: number
  isDragging?: boolean
}) {
  const { t, localize } = useShellTranslation()
  const thumbnailWidth = 200
  const thumbnailHeight = 280
  const strictPosition = (page as any).strictPosition
  const isLocked = strictPosition === 'start' || strictPosition === 'end'

  return (
    <div
      className={`uhuu:flex uhuu:items-center uhuu:justify-center uhuu:border uhuu:relative uhuu:rounded-lg uhuu:bg-(--uhuu-shell-surface) uhuu:overflow-hidden uhuu:transition-all ${
        isDragging
          ? "uhuu:opacity-50 uhuu:border-gray-400 uhuu:shadow-xl uhuu:scale-105"
          : isLocked
          ? "uhuu:border-gray-300 uhuu:bg-gray-50"
          : "uhuu:border-gray-200 uhuu:group-hover/drag-item:border-gray-300 uhuu:group-hover/drag-item:shadow-md"
      }`}
    >      
      <div
        className="uhuu:flex uhuu:items-center uhuu:justify-center"
        style={{
          width: `${thumbnailWidth}px`,
          height: `${thumbnailHeight}px`,
        }}
      >
        {/* Default content rendering */}
        {page.content || (
          <div className="uhuu:text-center uhuu:p-4">
            <div className="uhuu:text-sm uhuu:font-medium uhuu:text-gray-700">{localize(page.label) || t('page.fallbackName', { number: index + 1 })}</div>
            <div className="uhuu:text-xs uhuu:text-gray-400 uhuu:mt-1 uhuu:font-mono">{page.id}</div>
          </div>
        )}
      </div>

      {/* Page number badge */}
      <div className="uhuu:absolute uhuu:top-2 uhuu:left-2 uhuu:z-20">
        <Badge variant="secondary" className={`uhuu:text-xs uhuu:min-w-[24px] uhuu:h-6 uhuu:font-medium uhuu:bg-(--uhuu-shell-surface)/95 uhuu:backdrop-blur-sm uhuu:flex uhuu:items-center uhuu:justify-center uhuu:shadow-sm uhuu:border uhuu:border-gray-200 ${isLocked ? 'uhuu:opacity-75' : ''}`}>
          {isLocked ? (
            <Lock className="uhuu:size-3 uhuu:text-gray-500" />
          ) : (
            <>
              <span className="uhuu:group-hover/drag-item:hidden">{index + 1}</span>
              <GripVertical className="uhuu:size-4 uhuu:text-gray-400 uhuu:hidden uhuu:group-hover/drag-item:block" />
            </>
          )}
        </Badge>
      </div>
    </div>
  )
}

export function PageOrderDialog<T extends PageItem>({
  open,
  onOpenChange,
  pages,
  onReorder,
  onRemove,
  renderThumbnail,
  pageComponents,
  payload,
  setup,
  title,
  description,
  gridColsClass = "uhuu-page-order-grid-cols",
}: PageOrderDialogProps<T>) {
  const shellI18n = useShellTranslation()
  const { t, localize } = shellI18n
  const resolvedTitle = localize(title) ?? t('reorderDialog.title')
  const resolvedDescription = localize(description) ?? t('reorderDialog.description')
  // Track local order changes - only apply on save
  const [localPages, setLocalPages] = React.useState<T[]>(pages)
  const [hasChanges, setHasChanges] = React.useState(false)
  const keyExtractor = (page: T) => page.id

  // Sync local state when pages prop changes (but only if dialog is closed or no local changes)
  React.useEffect(() => {
    if (!open) {
      setLocalPages(pages)
      setHasChanges(false)
    } else if (!hasChanges) {
      setLocalPages(pages)
    } else {
      const localIds = new Set(localPages.map(keyExtractor))
      const shouldSync = localIds.size !== pages.length || pages.some((page) => !localIds.has(keyExtractor(page)))
      if (shouldSync) {
        setLocalPages(pages)
      }
    }
  }, [pages, open, hasChanges, localPages])

  const handleLocalReorder = (newOrder: T[]) => {
    setLocalPages(newOrder)
    setHasChanges(true)
  }

  const handleSave = () => {
    onReorder(localPages)
    setHasChanges(false)
    onOpenChange(false)
  }

  const handleCancel = () => {
    setLocalPages(pages)
    setHasChanges(false)
    onOpenChange(false)
  }

  // Auto-create default renderThumbnail if pageComponents provided and no valid custom renderThumbnail
  const defaultRenderThumbnail = React.useMemo(() => {    
    // Only auto-create if renderThumbnail is not provided or is not a function
    if ((!renderThumbnail || typeof renderThumbnail !== 'function') && pageComponents) {
      return createDefaultRenderThumbnail({ pageComponents, payload, setup, i18n: shellI18n })
    }
    return null
  }, [renderThumbnail, pageComponents, payload, setup, shellI18n])
  
  const renderPageThumbnail = (page: T, index: number, isDragging?: boolean) => {
    const strictPosition = (page as any).strictPosition
    const isLocked = strictPosition === 'start' || strictPosition === 'end'
    const showRemove = !!onRemove && !isLocked

    const handleRemove = (event: React.MouseEvent<HTMLButtonElement>) => {
      event.preventDefault()
      event.stopPropagation()
      if (!onRemove) return
      onRemove(page)
      setLocalPages((prev) => prev.filter((item) => keyExtractor(item) !== keyExtractor(page)))
      setHasChanges(true)
    }

    // Priority: 1. Custom renderThumbnail (if it's a function), 2. Auto-created defaultRenderThumbnail, 3. DefaultPageThumbnail
    const content = renderThumbnail && typeof renderThumbnail === 'function'
      ? renderThumbnail(page, index, isDragging)
      : defaultRenderThumbnail
      ? defaultRenderThumbnail(page as any, index, isDragging)
      : <DefaultPageThumbnail page={page} index={index} isDragging={isDragging} />

    return (
      <div className="uhuu:relative uhuu:inline-block uhuu:align-top">
        {content}
        {showRemove && (
          <button
            type="button"
            title={t('reorderDialog.remove')}
            onClick={handleRemove}
            onPointerDown={(event) => event.stopPropagation()}
            className="uhuu:group/remove-btn uhuu:absolute uhuu:-top-3 uhuu:-right-3 uhuu:z-30 uhuu:hidden uhuu:h-6 uhuu:w-6 uhuu:items-center uhuu:justify-center uhuu:rounded-full uhuu:bg-(--uhuu-shell-surface)/50 uhuu:hover:bg-(--uhuu-shell-surface) uhuu:text-gray-900 uhuu:backdrop-blur-md uhuu:group-hover/drag-item:flex uhuu:border uhuu:border-gray-200"
          >
            <GripVertical className="uhuu:size-3.5 uhuu:opacity-60 uhuu:group-hover/remove-btn:hidden" />
            <Plus className="uhuu:size-3.5 uhuu:rotate-45 uhuu:hidden uhuu:group-hover/remove-btn:block" />
          </button>
        )}
      </div>
    )
  }

  const renderEmptyState = () => (
    <div className="uhuu:text-center uhuu:py-20">
      <div className="uhuu:w-12 uhuu:h-12 uhuu:bg-gray-50 uhuu:rounded-lg uhuu:flex uhuu:items-center uhuu:justify-center uhuu:mx-auto uhuu:mb-3">
        <ArrowUpDown className="uhuu:w-6 uhuu:h-6 uhuu:text-gray-400" />
      </div>
      <div className="uhuu:text-base uhuu:font-medium uhuu:text-gray-900 uhuu:mb-1">{t('reorderDialog.emptyTitle')}</div>
      <p className="uhuu:text-sm uhuu:text-gray-500">{t('reorderDialog.emptyDescription')}</p>
    </div>
  )

  // Check if an item has strictPosition and should be disabled from dragging
  const isItemDisabled = React.useCallback((page: T) => {
    const strictPosition = (page as any).strictPosition;
    return strictPosition === 'start' || strictPosition === 'end';
  }, []);

  // Check if an item can be dropped at a specific position
  const canDropAt = React.useCallback((draggedItem: T, targetIndex: number, items: T[]) => {
    const draggedPosition = (draggedItem as any).strictPosition;
    
    // Items with strictPosition cannot be dragged (should be caught by isItemDisabled, but double-check)
    if (draggedPosition === 'start' || draggedPosition === 'end') {
      return false;
    }

    // Find the boundaries of start, middle, and end sections
    let startEndIndex = -1;
    let endStartIndex = items.length;
    
    for (let i = 0; i < items.length; i++) {
      const position = (items[i] as any).strictPosition;
      if (position === 'start') {
        startEndIndex = i;
      } else if (position === 'end' && endStartIndex === items.length) {
        endStartIndex = i;
        // Don't break - continue to find all end items
      }
    }

    // Regular items can only be dropped in the middle section
    // (after all start items and before all end items)
    if (targetIndex <= startEndIndex) {
      return false;
    }

    if (targetIndex >= endStartIndex) {
      return false;
    }

    return true;
  }, []);

  return (
    <Sheet open={open} onOpenChange={(newOpen) => {
      // Only allow closing via explicit cancel/save buttons
      if (!newOpen) {
        handleCancel()
      }
    }}>
      <SheetContent 
        side="bottom" 
        className="uhuu:h-[90vh] uhuu:p-0 uhuu:gap-0 uhuu:w-full uhuu:max-w-none uhuu:flex uhuu:flex-col uhuu:[&>button]:hidden"
        onPointerDownOutside={(e) => {
          // Prevent closing when clicking outside - use cancel/save buttons instead
          e.preventDefault()
        }}
        onEscapeKeyDown={(e) => {
          // Prevent escape from closing - use cancel button instead
          e.preventDefault()
        }}
        data-uhuu-editor
      >
        <SheetHeader className="uhuu:border-b uhuu:border-gray-200 uhuu:p-4">
          <div className="uhuu:flex uhuu:items-end uhuu:gap-3">
            <div className="uhuu:w-8 uhuu:h-8 uhuu:bg-gray-100 uhuu:rounded-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:shrink-0 uhuu:mb-0.5">
              <ArrowUpDown className="uhuu:w-4 uhuu:h-4" />
            </div>
            <div className="uhuu:flex-1">
              <SheetTitle className="uhuu:text-base uhuu:font-medium uhuu:text-gray-900 uhuu:leading-tight">{resolvedTitle}</SheetTitle>
              <SheetDescription className="uhuu:text-xs uhuu:text-gray-400 uhuu:mt-0.5">{resolvedDescription}</SheetDescription>
            </div>
            <Badge variant="outline" className="uhuu:text-xs uhuu:mb-0.5 uhuu:mr-8">
              {t('page.count', { count: localPages.length })}
            </Badge>
          </div>
        </SheetHeader>

        <div className="uhuu:flex-1 uhuu:overflow-hidden uhuu:flex uhuu:flex-col">
          <div className="uhuu:flex-1 uhuu:overflow-auto uhuu:p-6 uhuu:bg-gray-50">
            <DragDropGrid
              items={localPages}
              onChange={handleLocalReorder}
              renderItem={renderPageThumbnail}
              keyExtractor={keyExtractor}
              renderEmptyState={renderEmptyState}
              gridColsClass={gridColsClass}
              className="uhuu:pb-4"
              isItemDisabled={isItemDisabled}
              canDropAt={canDropAt}
            />
          </div>
        </div>

        <SheetFooter className="uhuu:border-t uhuu:border-gray-200 uhuu:px-4 uhuu:py-3 uhuu:gap-3">
          <Button
            variant="outline"
            onClick={handleCancel}
          >
            {t('reorderDialog.cancel')}
          </Button>
          <Button
            variant="default"
            onClick={handleSave}
            disabled={!hasChanges}
          >
            {t('reorderDialog.save')}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  )
}
