import React, { CSSProperties, ReactNode, forwardRef, useContext, useEffect, useRef } from 'react';
import { ConfigContext } from '../config/config-provider';
import Sheet from './sheet-static';
import { resolveBinding } from './spread-core';
import type { BindingConfig, CoverPanelSide, CoverSheetKind, ResolvedBinding } from './spread-core';
import { isDev } from '../utility/is-dev';

export interface CoverSpreadOverlayArgs {
  pageNo: number;
  side: CoverPanelSide;
  sheet: CoverSheetKind;
}

export interface CoverSpreadProps {
  /** `outer` = back cover · spine · front cover. `inner` = inside front · blank spine + glue · inside back. */
  sheet: CoverSheetKind;
  /** Left panel content (back cover on the outer sheet, inside front cover on the inner sheet). */
  left: ReactNode;
  /** Right panel content (front cover on the outer sheet, inside back cover on the inner sheet). */
  right: ReactNode;
  /** Spine artwork. Rendered on the outer sheet only; the inner spine is always blank paper. */
  spine?: ReactNode;
  /** Original document page numbers `[left, right]`, forwarded to `overlay`. */
  pageNo?: [number, number];
  overlay?: (args: CoverSpreadOverlayArgs) => ReactNode;
  /** Overrides `binding` from the surrounding `Static.Pagination` setup. */
  binding?: BindingConfig | null;
  /** Show the hatched spine/glue guides and each panel's bleed outline (screen only). Falls back to the Pagination setup. */
  showBleed?: boolean;
  className?: string;
  style?: CSSProperties;
  leftClassName?: string;
  rightClassName?: string;
  leftPageKey?: string;
  rightPageKey?: string;
}

const formatMm = (value: number) => `${Number(value.toFixed(4))}mm`;

function useMissingBindingWarning(sheet: CoverSheetKind, binding: ResolvedBinding | null) {
  const warned = useRef(false);
  useEffect(() => {
    if (binding || warned.current || !isDev()) return;
    warned.current = true;
    console.warn(
      `[uhuu-components] Static.CoverSpread sheet="${sheet}" rendered without a perfect binding. ` +
        'Pass binding={{ spine, glue }} on the Pagination setup (or the binding prop) to compose a cover spread. ' +
        'Rendering the two panels as plain sheets instead.'
    );
  }, [sheet, binding]);
}

/**
 * One physical cover sheet of a perfect-bound product: two ordinary `Static.Sheet`
 * panels clipped at the spine, plus the spine strip and (inner sheet) the glue
 * masks. Geometry comes from `pageFormat.binding` via `Static.Pagination`; the
 * sheet size itself is driven by the `--uhuu-sheet-*` root vars so `@page`
 * prints it at the printer's size. See docs/printer-cover-spine-support.md §6.3.
 */
export const CoverSpread = forwardRef<HTMLDivElement, CoverSpreadProps>(function CoverSpread(
  {
    sheet,
    left,
    right,
    spine,
    pageNo,
    overlay,
    binding: bindingProp,
    showBleed,
    className = '',
    style,
    leftClassName = '',
    rightClassName = '',
    leftPageKey,
    rightPageKey,
  },
  ref
) {
  const config = useContext(ConfigContext) as any;
  const binding: ResolvedBinding | null =
    bindingProp !== undefined ? resolveBinding(bindingProp) : (config?.page?.binding ?? null);
  const guides = showBleed ?? config?.page?.showBleed ?? false;
  const [leftNo, rightNo] = pageNo ?? [0, 0];

  useMissingBindingWarning(sheet, binding);

  const panelOverlay = (side: CoverPanelSide) =>
    overlay ? ({ pageNo: no }: { pageNo: number }) => overlay({ pageNo: no, side, sheet }) : undefined;

  const leftSheet = (
    <Sheet
      className={`uhuu-page-sheet--panel ${leftClassName}`.trim()}
      pageNo={leftNo}
      overlay={panelOverlay('left')}
      showBleed={guides}
      data-page-key={leftPageKey}
    >
      {left}
    </Sheet>
  );

  const rightSheet = (
    <Sheet
      className={`uhuu-page-sheet--panel ${rightClassName}`.trim()}
      pageNo={rightNo}
      overlay={panelOverlay('right')}
      showBleed={guides}
      data-page-key={rightPageKey}
    >
      {right}
    </Sheet>
  );

  // No spine to compose around: degrade to the two plain cover pages so the
  // document still renders (and prints) at the single-page size.
  if (!binding) {
    return (
      <>
        {leftSheet}
        {rightSheet}
      </>
    );
  }

  const blank = sheet === 'inner';
  const showGlue = blank && binding.glue > 0;

  return (
    <div
      ref={ref}
      className={`uhuu-page-sheet uhuu-cover-spread ${className}`.trim()}
      style={style}
      data-sheet={sheet}
      data-spine={binding.spine}
      data-glue={binding.glue}
    >
      <div className="uhuu-spread-panel" data-side="left">
        {leftSheet}
      </div>

      <div className="uhuu-spread-spine" data-blank={blank ? 'true' : 'false'}>
        {!blank && spine}
        {guides && (
          <div
            className="uhuu-spread-guide"
            data-label={`spine ${formatMm(binding.spine)}${blank ? ' · blank' : ''}`}
          />
        )}
      </div>

      <div className="uhuu-spread-panel" data-side="right">
        {rightSheet}
      </div>

      {showGlue &&
        (['left', 'right'] as const).map((side) => (
          <div key={side} className="uhuu-glue-zone" data-side={side}>
            {guides && <div className="uhuu-spread-guide" data-label={`glue ${formatMm(binding.glue)}`} />}
          </div>
        ))}
    </div>
  );
});

export default CoverSpread;
